'use strict';

function inspectDetections(detections, targetLabel, minimumScore) {
  if (!Array.isArray(detections) || typeof targetLabel !== 'string' || targetLabel === '' ||
      !Number.isFinite(minimumScore) || minimumScore < 0 || minimumScore > 1) {
    throw new TypeError('invalid arguments');
  }
  const checked = detections.map((item, index) => {
    const box = item && item.box;
    if (!item || typeof item !== 'object' || typeof item.label !== 'string' || item.label === '' ||
        !Number.isFinite(item.score) || item.score < 0 || item.score > 1 || !box ||
        !Number.isFinite(box.x) || !Number.isFinite(box.y) || !Number.isFinite(box.width) ||
        !Number.isFinite(box.height) || box.width < 0 || box.height < 0) {
      throw new TypeError('malformed detection');
    }
    return { item, index };
  });
  const matches = checked
    .filter(({ item }) => item.label === targetLabel && item.score > minimumScore)
    .sort((a, b) => b.item.score - a.item.score || a.index - b.index)
    .map(({ item }) => ({ label: item.label, score: item.score, box: { ...item.box } }));
  return { count: detections.length, found: matches.length > 0, matches };
}

module.exports = { inspectDetections };

