'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['inspectDetections']);
const { inspectDetections } = api;

const detections = [
  { label: 'cat', score: 0.8, box: { x: 1, y: 2, width: 3, height: 4 } },
  { label: 'dog', score: 1, box: { x: -2, y: 0, width: 0, height: 5 } },
  { label: 'cat', score: 0.9, box: { x: 4, y: 5, width: 6, height: 7 } },
  { label: 'cat', score: 0.8, box: { x: 8, y: 9, width: 10, height: 11 } },
  { label: 'Cat', score: 1, box: { x: 0, y: 0, width: 1, height: 1 } }
];
const snapshot = structuredClone(detections);
const result = inspectDetections(detections, 'cat', 0.8);
assert.strictEqual(result.count, 5);
assert.strictEqual(result.found, true);
assert.deepStrictEqual(result.matches, [detections[2], detections[0], detections[3]]);
assert.deepStrictEqual(detections, snapshot);
assert.notStrictEqual(result.matches[0], detections[2]);
assert.notStrictEqual(result.matches[0].box, detections[2].box);
assert.notStrictEqual(result.matches[1], detections[0]);
assert.notStrictEqual(result.matches[2], detections[3]);

result.matches[0].label = 'changed';
result.matches[0].box.x = 999;
assert.deepStrictEqual(detections, snapshot);

assert.deepStrictEqual(inspectDetections([], 'anything', 0), {
  count: 0,
  found: false,
  matches: []
});
assert.deepStrictEqual(inspectDetections(detections, 'cat', 1), {
  count: 5,
  found: false,
  matches: []
});
assert.strictEqual(inspectDetections(detections, 'Cat', 1).found, true);

const valid = { label: 'x', score: 0, box: { x: 0, y: 0, width: 0, height: 0 } };
for (const badDetections of [
  null,
  {},
  [null],
  [{ ...valid, label: '' }],
  [{ ...valid, score: NaN }],
  [{ ...valid, score: Infinity }],
  [{ ...valid, score: -0.01 }],
  [{ ...valid, score: 1.01 }],
  [{ ...valid, box: null }],
  [{ ...valid, box: { x: NaN, y: 0, width: 1, height: 1 } }],
  [{ ...valid, box: { x: 0, y: 0, width: -1, height: 1 } }],
  [{ ...valid, box: { x: 0, y: 0, width: 1, height: -1 } }]
]) {
  assert.throws(() => inspectDetections(badDetections, 'x', 0), TypeError);
}
for (const target of ['', null, 3]) {
  assert.throws(() => inspectDetections([valid], target, 0), TypeError);
}
for (const score of [NaN, Infinity, -1, 1.1, '0.5']) {
  assert.throws(() => inspectDetections([valid], 'x', score), TypeError);
}

